/**
 * 功能描述
 *
 * @since 2026-02-06
 */
@Component
public class BlockAllocCalculator {
    private static final OssLog LOGGER = OssLogFactory.getLogger(BlockAllocCalculator.class);

    private static final String UNDER_LINE = "_";

    @Autowired private CapacityDBMapper capacityDBMapper;

    @Autowired private CapacityCommDBMapper capacityCommDBMapper;

    @Autowired private CapacityFactDBMapper capacityFactDBMapper;

    @Autowired private UnAllocReasonUtil unAllocReasonUtil;

    /**
     * 处理区块级放号
     *
     * @param scenes scenes
     * @param dateKey dateKey
     */
    public void processVenueScenes(List<SceneInfo> scenes, Timestamp dateKey) {
        int[] sceneIds = scenes.stream().mapToInt(SceneInfo::getSceneId).toArray();
        Map<Integer, List<AllocResult>> latestCellResults = capacityFactDBMapper.getLatestVenueCellInfos(sceneIds,
            dateKey).stream().collect(Collectors.groupingBy(AllocResult::getSceneId));
        LOGGER.info("debug venue latestCellResults: {}", latestCellResults);

        for (SceneInfo scene : scenes) {
            try {
                capacityDBMapper.deleteRegionBlockResults(new int[] {scene.getSceneId()});
                LOGGER.info("Processing venue scene: {}", scene.getSceneCode());
                // 进行区块级汇总
                processVenueScene(scene, latestCellResults.get(scene.getSceneId()), dateKey);
                LOGGER.info("Venue scene {} processed successfully", scene.getSceneCode());
            } catch (Exception e) {
                LOGGER.error("Failed to process venue scene: " + scene.getSceneCode(), e);
            }
        }
    }

    /**
     * 处理单个场馆场景
     *
     * @param scene 场景
     * @param allocResults 放号结果
     * @param dateKey 周期
     */
    private void processVenueScene(SceneInfo scene, List<AllocResult> allocResults, Timestamp dateKey) {
        try {
            List<AllocResult> histVenueResults = capacityDBMapper.getVenueHistResults(scene.getSceneId());
            List<AllocResult> mergeAllocResults;
            if (CollectionUtils.isEmpty(allocResults)) {
                mergeAllocResults = histVenueResults;
            } else {
                mergeAllocResults = Stream.concat(allocResults.stream(), histVenueResults.stream())
                    .collect(Collectors.toMap(
                        cell -> cell.getPackageId() + UNDER_LINE + cell.getGNodeBId() + UNDER_LINE + cell.getCellId(),
                        data -> data, (existing, replacement) -> existing))
                    .values()
                    .stream()
                    .toList();
            }
            LOGGER.info("Processing venue scene {} for block-level allocation at time: {}", scene, dateKey);
            if (CollectionUtils.isEmpty(mergeAllocResults)) {
                LOGGER.info("venue alloc result is empty: {}", mergeAllocResults);
                return;
            }
            Map<AllocResult, AllocResult> sceneCellUnAllocResults = unAllocReasonUtil.getSceneCellUnActiveResults(
                scene.getSceneId()).stream().collect(Collectors.toMap(result -> result, result -> result, (a, b) -> a));
            mergeAllocResults.forEach(cell -> {
                AllocResult allocResult = sceneCellUnAllocResults.get(cell);
                if (allocResult != null) {
                    cell.setRemark(allocResult.getRemark());
                    cell.setResult(NoAllocTypeEnum.UNKNOWN.getSpaceNum());
                }
            });

            Map<AllocResult, String> venueCells = capacityCommDBMapper.getVenueCells(scene.getRelateRegionId())
                .stream()
                .collect(Collectors.toMap(cell -> cell, AllocResult::getBlockName, (a, b) -> b));
            Map<String, RegionResult> blockPackageResults = new HashMap<>();
            for (AllocResult allocResult : mergeAllocResults) {
                String blockName = venueCells.getOrDefault(allocResult, "");
                int packageId = allocResult.getPackageId();
                String groupKey = blockName + UNDER_LINE + packageId;
                blockPackageResults.put(groupKey, handelUnAllocReason(allocResult, blockPackageResults, blockName));
            }

            if (MapUtils.isEmpty(blockPackageResults)) {
                LOGGER.info("Scene {} block result is empty.", scene);
                return;
            }

            blockPackageResults.values()
                .forEach(regionResult -> capacityDBMapper.insertVenueResults(regionResult, dateKey));
        } catch (Exception e) {
            LOGGER.error("Failed to process venue scene: {}", scene.getSceneCode(), e);
        }
    }

    private RegionResult handelUnAllocReason(AllocResult allocResult, Map<String, RegionResult> blockPackageResults,
        String blockName) {
        int packageId = allocResult.getPackageId();
        String blockKey = blockName + UNDER_LINE + packageId;
        RegionResult regionResult = blockPackageResults.getOrDefault(blockKey,
            new RegionResult(allocResult.getSceneId(), blockName, allocResult.getPackageId()));
        if (StringUtils.isEmpty(allocResult.getRemark())) {
            regionResult.setResult(regionResult.getResult() + allocResult.getResult());
            return regionResult;
        }
        if (UNACTIVE.equals(AllocErrorType.toEnumByMessageOrKey(allocResult.getRemark()))) {
            regionResult.setDeactiveCell(regionResult.getDeactiveCell() + 1);
        }
        if (allocResult.getResult() == 0) {
            regionResult.setResourceShortfallCell(regionResult.getResourceShortfallCell() + 1);
            return regionResult;
        }
        if (allocResult.getResult() < 0) {
            regionResult.setAbnormalCell(regionResult.getAbnormalCell() + 1);
        }
        return regionResult;
    }
}
